namespace Ordering;

/// <summary>Handles product returns, the refunds they trigger and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnsReturnProcessor _returnProcessor;
    private readonly ReturnsEligibilityService _eligibilityService;
    private readonly ReturnsRefundService _refundService;
    private readonly ReturnsRestockingService _restockingService;

    public ReturnsHandler()
    {
        var processedReturns = new ReturnsProcessedRegistry();
        var restockInventory = new ReturnsRestockInventory();

        _returnProcessor = new ReturnsReturnProcessor(processedReturns, restockInventory);
        _eligibilityService = new ReturnsEligibilityService(processedReturns);
        _refundService = new ReturnsRefundService();
        _restockingService = new ReturnsRestockingService(restockInventory);
    }

    public string ProcessReturn(Order order, Customer customer) =>
        _returnProcessor.Process(order, customer);

    public bool IsReturnable(Order order) =>
        _eligibilityService.IsReturnable(order);

    public decimal ComputeRefund(Order order) =>
        _refundService.ComputeRefund(order);

    public void LogRefund(Order order, decimal amount) =>
        _refundService.LogRefund(order, amount);

    public int Restock(Order order) =>
        _restockingService.Restock(order);
}

internal sealed class ReturnsReturnProcessor
{
    private readonly ReturnsProcessedRegistry _processedReturns;
    private readonly ReturnsRestockInventory _restockInventory;

    public ReturnsReturnProcessor(
        ReturnsProcessedRegistry processedReturns,
        ReturnsRestockInventory restockInventory)
    {
        _processedReturns = processedReturns;
        _restockInventory = restockInventory;
    }

    public string Process(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (_processedReturns.Contains(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return "quantity too high";

            _restockInventory.AddPending(line.Sku, line.Quantity);
        }

        if (!_restockInventory.HasEntries)
            return "no returnable lines";

        _processedReturns.Add(order.Reference);
        return "accepted";
    }
}

internal sealed class ReturnsEligibilityService
{
    private readonly ReturnsProcessedRegistry _processedReturns;

    public ReturnsEligibilityService(ReturnsProcessedRegistry processedReturns)
    {
        _processedReturns = processedReturns;
    }

    public bool IsReturnable(Order order)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (_processedReturns.Contains(order.Reference))
            return false;

        int valid = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (string.IsNullOrEmpty(line.Sku))
                continue;
            if (line.Quantity > 100)
                continue;
            if (line.Quantity >= 1 && line.Quantity <= 100)
                valid++;
        }

        return valid > 0;
    }
}

internal sealed class ReturnsRefundService
{
    private const decimal UnitRefund = 5m;
    private readonly List<string> _refundLog = new();

    public decimal ComputeRefund(Order order)
    {
        decimal refund = 0m;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 50)
                refund += line.Quantity * UnitRefund * 0.9m;
            else if (line.Quantity > 10)
                refund += line.Quantity * UnitRefund * 0.95m;
            else if (line.Quantity > 1)
                refund += line.Quantity * UnitRefund;
            else
                refund += UnitRefund;
        }

        if (_refundLog.Count > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;

        return refund < 0m ? 0m : refund;
    }

    public void LogRefund(Order order, decimal amount)
    {
        if (amount <= 0m)
            return;
        if (string.IsNullOrEmpty(order.Reference))
            return;
        if (_refundLog.Count == 0 || amount > 100m)
            _refundLog.Add($"{order.Reference}:{amount}");
        else if (amount > 50m)
            _refundLog.Add($"{order.Reference}:large:{amount}");
        else if (amount > 10m)
            _refundLog.Add($"{order.Reference}:mid:{amount}");
        else
            _refundLog.Add($"{order.Reference}:small:{amount}");
        if (_refundLog.Count > 500 && amount > 1000m)
            _refundLog.Add($"{order.Reference}:flag");
    }
}

internal sealed class ReturnsRestockingService
{
    private readonly ReturnsRestockInventory _restockInventory;

    public ReturnsRestockingService(ReturnsRestockInventory restockInventory)
    {
        _restockInventory = restockInventory;
    }

    public int Restock(Order order)
    {
        int moved = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;

            var sku = line.Sku;
            if (string.IsNullOrEmpty(sku))
                continue;
            if (line.Quantity > 100)
                continue;

            if (_restockInventory.TryGetPending(sku, out var pending) && pending > 0)
            {
                moved += pending;
                _restockInventory.SetPending(sku, 0);
            }
            else if (line.Quantity > 50)
            {
                _restockInventory.SetPending(sku, line.Quantity / 2);
            }
            else if (line.Quantity > 0)
            {
                _restockInventory.SetPending(sku, line.Quantity);
            }

            if (moved > 100000)
                break;
        }

        return moved;
    }
}

internal sealed class ReturnsProcessedRegistry
{
    private readonly HashSet<string> _processedReferences = new(StringComparer.Ordinal);

    public bool Contains(string reference) => _processedReferences.Contains(reference);

    public void Add(string reference) => _processedReferences.Add(reference);
}

internal sealed class ReturnsRestockInventory
{
    private readonly Dictionary<string, int> _pendingBySku = new(StringComparer.Ordinal);

    public bool HasEntries => _pendingBySku.Count != 0;

    public void AddPending(string sku, int quantity)
    {
        _pendingBySku[sku] = _pendingBySku.TryGetValue(sku, out var current)
            ? current + quantity
            : quantity;
    }

    public bool TryGetPending(string sku, out int quantity) =>
        _pendingBySku.TryGetValue(sku, out quantity);

    public void SetPending(string sku, int quantity) =>
        _pendingBySku[sku] = quantity;
}
